// =====================================================================
//  SETUP: the only node you edit.
//  Every block marked EXAMPLE is working demo content. Replace it with
//  your own before you switch the schedules on.
// =====================================================================

const engine =
  $('Daily 07:00: Post Engagement').isExecuted ? 'engagement' :
  $('Daily 06:00: Keyword Listening').isExecuted ? 'keywords' :
  $('Monday 08:00: Job Changes and Hiring').isExecuted ? 'people' :
  'demo';

return [{ json: {
  engine,

  // 1. WHO YOU SELL TO. EXAMPLE: rewrite in plain words for your business.
  //    Jev reads this to judge buyer fit, and to spot sellers pitching the same thing.
  icp: {
    what_we_sell: 'We build and run the sales system (CRM, pipeline, follow-up, reporting, outbound) for companies with a sales team',
    ideal_buyer: 'Founder, CEO, COO, VP or Head of Sales, Head of RevOps at a company that sells a high-ticket product or service through human salespeople',
    not_a_fit: 'Low-ticket or self-serve products, solo operators with no sales team, agencies or consultants selling sales or CRM services, software vendors, recruiters, job seekers, students'
  },

  // 2. PAIN ANGLES AND OPENERS. EXAMPLE: keep the structure, rewrite the words.
  //    Jev picks the angle closest to what the person wrote or engaged with.
  //    `opener` is sent to HeyReach as the custom variable {signal_opener}.
  //    Write it the way you would type it. No pitch in the first line.
  angles: {
    crm_admin: {
      means: 'Reps lose time to CRM data entry, logging, or manual admin instead of selling',
      opener: 'Saw your note on reps losing time to CRM admin. Is it the logging itself, or chasing stage updates after calls?'
    },
    follow_up: {
      means: 'Leads or deals slip because follow-up is slow, missed, or inconsistent',
      opener: 'Saw your point on leads going cold before anyone follows up. Is that a speed problem or a who-owns-it problem on your side?'
    },
    pipeline_visibility: {
      means: 'Leadership cannot trust the pipeline, forecast, or reporting',
      opener: 'Saw your post on not trusting the pipeline numbers. Is it the data going in, or how the stages are defined?'
    },
    outbound_broken: {
      means: 'Outbound or cold outreach has stopped producing meetings',
      opener: 'Saw your take on outbound drying up. Did it fade gradually, or drop after one specific change?'
    },
    scaling_team: {
      means: 'Hiring or onboarding reps, or deciding whether to add sales headcount',
      opener: 'Saw you are thinking about adding reps. Have you mapped how much of the current team\'s week goes to non-selling work?'
    }
  },

  // 3. SCORING. Weights add up to 1. A lead at or above hot_score gets routed.
  weights: { buyer_fit: 0.55, pain: 0.35, stacking: 0.10 },
  hot_score: 70,

  // 4. WHERE HOT LEADS GO. Anything left empty ('' or 0 or false) is skipped,
  //    so the workflow runs end to end before you connect every tool.
  heyreach_campaign_id: 0,        // PASTE: HeyReach campaign ID. The campaign must be running.
  heyreach_sender_account_id: 0,  // PASTE: the LinkedIn sender account ID inside HeyReach
  hubspot_enabled: false,         // true once the HubSpot credential is connected
  enrich_emails: false,           // true = Apify email lookup on hot LinkedIn leads only (~$10 per 1k)
  telegram_chat_id: ''            // PASTE: your Telegram chat ID for hot-lead alerts
} }];

// DEMO DATA. Three made-up signals so you can watch scoring work before connecting Apify.
// Needs only the TypeSafe credential. Nothing here is pushed to HeyReach or HubSpot.
const run = 'demo-run-' + $execution.id;
const demo = [
  { person_url: 'https://www.linkedin.com/in/demo-jane-example', person_name: 'Jane Example (demo)', headline: 'VP Sales at Northwind Solar, 40-person sales team', platform: 'linkedin', signal_type: 'post_comment', weight: 3, source_label: 'Demo: competitor post', context_text: 'Their comment: honestly my reps spend two hours a day logging calls in the CRM. Nobody wants to admit it.', context_url: run + '/1' },
  { person_url: 'https://www.linkedin.com/in/demo-mark-agency', person_name: 'Mark Agency (demo)', headline: 'Founder @ PipelineCraft | I help B2B teams fix their CRM | HubSpot Partner', platform: 'linkedin', signal_type: 'keyword_post', weight: 4, source_label: 'Demo: keyword', context_text: 'Their post: 5 reasons your reps hate your CRM (and how my agency fixes it in 30 days). DM me.', context_url: run + '/2' },
  { person_url: 'https://www.linkedin.com/in/demo-tom-legal', person_name: 'Tom Harbor (demo)', headline: 'CEO at Harbor Legal Group, 12 partners', platform: 'linkedin', signal_type: 'keyword_post', weight: 4, source_label: 'Demo: keyword', context_text: 'Their post: we get plenty of inbound consults but half of them never hear back from us within a day. How are other firms handling intake follow-up?', context_url: run + '/3' }
];
return demo.map(d => ({ json: d }));

// Turns the active rows of the Sources table into Apify runs for the engine that fired.
// Returns nothing when there is nothing to track, so an empty engine costs nothing.
const cfg = $('SETUP').first().json;
const rows = $input.all().map(i => i.json).filter(r => r.active && r.target);
const of = kind => rows.filter(r => r.kind === kind).map(r => r.target);
const runs = [];

if (cfg.engine === 'engagement' && of('engagement_profile').length) {
  // Posts from tracked profiles or company pages, plus who reacted and commented.
  // 'short' profile mode is free and returns normal /in/ profile URLs, so the same
  // person matches across engines and in HeyReach. Max 10 authors per run.
  runs.push({ actor: 'harvestapi~linkedin-post-search', input: {
    authorUrls: of('engagement_profile').slice(0, 10), postedLimit: 'week', sortBy: 'date', maxPosts: 30,
    scrapeReactions: true, maxReactions: 200, reactionsProfileScraperMode: 'short', postNestedReactions: false,
    scrapeComments: true, maxComments: 100, commentsProfileScraperMode: 'short', postNestedComments: false
  } });
}

if (cfg.engine === 'keywords') {
  if (of('keyword').length) runs.push({ actor: 'harvestapi~linkedin-post-search', input: {
    searchQueries: of('keyword'), postedLimit: '24h', sortBy: 'date', maxPosts: 50,
    scrapeComments: true, maxComments: 30, profileScraperMode: 'short', commentsProfileScraperMode: 'short'
  } });
  if (of('x_keyword').length) runs.push({ actor: 'apidojo~tweet-scraper', input: {
    searchTerms: of('x_keyword'), sort: 'Latest', maxItems: 100, tweetLanguage: 'en',
    start: $now.minus({ days: 1 }).toFormat('yyyy-MM-dd')
  } });
  if (of('reddit_keyword').length) runs.push({ actor: 'trudax~reddit-scraper-lite', input: {
    searches: of('reddit_keyword'), sort: 'new', time: 'day', maxItems: 50, maxPostCount: 50,
    searchPosts: true, skipComments: true, skipUserPosts: true, skipCommunity: true,
    includeNSFW: false, proxy: { useApifyProxy: true }
  } });
}

if (cfg.engine === 'people') {
  if (of('champion').length) runs.push({ actor: 'harvestapi~linkedin-profile-scraper', input: {
    profileScraperMode: 'Profile details no email ($4 per 1k)', queries: of('champion')
  } });
  const accounts = rows.filter(r => r.kind === 'hiring_account');
  if (accounts.length) runs.push({ actor: 'harvestapi~linkedin-job-search', input: {
    company: accounts.map(a => a.target),
    jobTitles: [...new Set(accounts.flatMap(a => String(a.notes || 'sales development representative').split(',').map(t => t.trim()).filter(Boolean)))],
    postedLimit: 'week', sortBy: 'date', maxItems: 100
  } });
}

return runs.map(r => ({ json: r }));

// Every Apify result becomes one signal shape:
// person_url, person_name, headline, platform, signal_type, weight, source_label, context_text, context_url.
// Champion lookups also emit a bookkeeping row that stores the employer seen today.
const cfg = $('SETUP').first().json;
const sources = $('Load Active Sources').all().map(i => i.json).filter(r => r.kind);
const items = $input.all().map(i => i.json).filter(x => x && typeof x === 'object' && !x.error);
const s = v => String(v || '');
const norm = u => s(u).split('?')[0].replace(/\/$/, '').replace(/^https?:\/\/(www\.)?/, '').toLowerCase();
const slug = u => { const m = s(u).match(/linkedin\.com\/in\/([^\/?#]+)/i); return m ? decodeURIComponent(m[1]).toLowerCase() : ''; };
const ofKind = k => sources.filter(r => r.kind === k);
const tracked = ofKind('engagement_profile').map(r => norm(r.target));
const out = [];
const add = o => { if (o.person_url && o.person_name) out.push({ json: o }); };

// Which tracked profile or keyword produced this signal
const labelForAuthor = url => {
  const a = norm(url);
  const r = ofKind('engagement_profile').find(x => a && norm(x.target) && a.startsWith(norm(x.target)));
  return r ? r.label : 'Tracked profile';
};
const labelForText = (text, kind, fallback) => {
  const t = s(text).toLowerCase();
  const r = ofKind(kind).find(k => s(k.target).toLowerCase().split(/\s+/).filter(w => w.length > 3).every(w => t.includes(w)));
  return r ? r.label : fallback;
};

// LinkedIn posts, reactions and comments
const posts = items.filter(it => it.author && it.content !== undefined);
const findPost = id => posts.find(p => s(p.id) === s(id) || s(p.linkedinUrl).includes(s(id || '#none#'))) || null;
const linkedinSignal = (who, type, weight, post, comment) => {
  if (!who || typeof who !== 'object') return;
  const url = who.linkedinUrl || who.profileUrl || who.url || '';
  if (!url || tracked.includes(norm(url))) return;
  const author = (post && post.author) || {};
  const kw = cfg.engine === 'keywords';
  add({
    person_url: url,
    person_name: who.name || [who.firstName, who.lastName].filter(Boolean).join(' '),
    headline: s(who.position || who.info || who.headline || who.occupation),
    platform: 'linkedin',
    signal_type: (kw ? 'keyword_' : 'post_') + type,
    weight,
    source_label: kw ? labelForText(post && post.content, 'keyword', 'LinkedIn keyword') : labelForAuthor(author.linkedinUrl),
    context_text: (comment ? 'Their comment: ' + s(comment).slice(0, 500) + '\n\n' : '') + 'Post by ' + (author.name || 'someone') + ': ' + s(post && post.content).slice(0, 900),
    context_url: (post && post.linkedinUrl) || ''
  });
};

const jobs = [];
const profiles = [];

for (const it of items) {
  // X / Twitter
  if (it.author && it.author.userName && (it.text || it.fullText)) {
    const text = it.fullText || it.text;
    add({ person_url: 'https://x.com/' + it.author.userName, person_name: it.author.name || it.author.userName, headline: s(it.author.description), platform: 'x', signal_type: 'x_keyword_post', weight: 3, source_label: labelForText(text, 'x_keyword', 'X keyword'), context_text: 'Their post: ' + s(text).slice(0, 900), context_url: it.url || it.twitterUrl || '' });
    continue;
  }
  // Reddit
  if (it.username && (it.title || it.body) && s(it.url).includes('reddit.com')) {
    const text = s(it.title) + '\n' + s(it.body);
    add({ person_url: 'https://www.reddit.com/user/' + it.username, person_name: it.username, headline: 'Posts in ' + s(it.communityName || it.parsedCommunityName), platform: 'reddit', signal_type: 'reddit_keyword_post', weight: 3, source_label: labelForText(text, 'reddit_keyword', 'Reddit keyword'), context_text: 'Their post: ' + text.slice(0, 900), context_url: it.url });
    continue;
  }
  if (cfg.engine === 'people') {
    if ((it.title || it.jobTitle) && !it.firstName) { jobs.push(it); continue; }
    if (it.firstName || it.publicIdentifier) { profiles.push(it); continue; }
  }
  // LinkedIn reaction or comment returned as its own item
  if (it.reactionType && it.actor) { linkedinSignal(it.actor, 'reaction', 1, findPost(it.postId), null); continue; }
  const commentText = it.commentary || it.text || it.comment;
  if (it.actor && commentText) { linkedinSignal(it.actor, 'comment', cfg.engine === 'keywords' ? 2 : 3, findPost(it.postId), commentText); continue; }
  // LinkedIn post (its author is the signal only in keyword search)
  if (it.author && it.content !== undefined) {
    if (cfg.engine === 'keywords') {
      const a = it.author;
      add({ person_url: a.linkedinUrl || '', person_name: a.name || '', headline: s(a.info || a.position || a.headline), platform: 'linkedin', signal_type: 'keyword_post', weight: 4, source_label: labelForText(it.content, 'keyword', 'LinkedIn keyword'), context_text: 'Their post: ' + s(it.content).slice(0, 900), context_url: it.linkedinUrl || '' });
    }
    for (const r of it.reactions || []) linkedinSignal(r.actor || r, 'reaction', 1, it, null);
    for (const c of it.comments || []) linkedinSignal(c.actor || c.author || c, 'comment', cfg.engine === 'keywords' ? 2 : 3, it, c.commentary || c.text);
  }
}

// Champions: compare today's employer with the one stored last run
const company = p => (p.currentPosition && p.currentPosition[0] && p.currentPosition[0].companyName) || (p.experience && p.experience[0] && p.experience[0].companyName) || p.companyName || '';
for (const c of ofKind('champion')) {
  const p = profiles.find(x => slug(x.linkedinUrl) === slug(c.target) || s(x.publicIdentifier).toLowerCase() === slug(c.target));
  if (!p) continue;
  const now = s(company(p)).trim();
  if (!now) continue;
  const before = s(c.last_value).trim();
  out.push({ json: { _bookkeeping: true, row_id: c.id, last_value: now } });
  if (before && before.toLowerCase() !== now.toLowerCase()) {
    add({ person_url: p.linkedinUrl || c.target, person_name: [p.firstName, p.lastName].filter(Boolean).join(' ') || c.label, headline: s(p.headline), platform: 'linkedin', signal_type: 'job_change', weight: 5, source_label: 'Champion: ' + (c.label || 'tracked'), context_text: 'Former champion moved from ' + before + ' to ' + now + '. New headline: ' + s(p.headline) + '. Notes: ' + s(c.notes), context_url: p.linkedinUrl || c.target });
  }
}

// Hiring: one account-level signal per company, open roles rolled up
const byAccount = {};
for (const j of jobs) {
  const cUrl = (j.company && (j.company.linkedinUrl || j.company.url)) || j.companyUrl || j.companyLinkedinUrl || '';
  const cName = (j.company && j.company.name) || j.companyName || '';
  const acct = ofKind('hiring_account').find(a => (cUrl && norm(cUrl).startsWith(norm(a.target))) || (cName && s(a.label).toLowerCase().includes(cName.toLowerCase())));
  if (!acct) continue;
  const g = byAccount[acct.target] = byAccount[acct.target] || { acct, name: cName, roles: [] };
  g.roles.push(s(j.title || j.jobTitle) + (j.location ? ' (' + s(j.location.linkedinText || j.location) + ')' : '') + ' ' + s(j.linkedinUrl || j.url));
}
for (const g of Object.values(byAccount)) {
  add({ person_url: g.acct.target, person_name: g.name || g.acct.label, headline: 'Company, not a person: ' + (g.name || g.acct.label) + ' is hiring ' + g.roles.length + ' matching role(s)', platform: 'linkedin_company', signal_type: 'hiring', weight: 3, source_label: g.acct.label || 'Hiring watch', context_text: 'Open roles posted this week:\n' + g.roles.slice(0, 8).join('\n'), context_url: g.acct.target.replace(/\/$/, '') + '/jobs/' });
}

return out;

// Drops anything already seen in the last 30 days, then counts every distinct signal
// each person produced across all engines (signal stacking).
const EXCLUDE = ['student', 'intern', 'recruiter', 'talent acquisition', 'open to work', 'seeking new', 'job seeker'];
const incoming = $('Collect Signals').all().map(i => i.json);
const history = $('Load Last 30 Days').all().map(i => i.json).filter(r => r.dedup_key);
const clean = u => String(u || '').split('?')[0].replace(/\/$/, '');
const seen = new Set(history.map(r => r.dedup_key));
const fresh = [];
for (const s of incoming) {
  const url = clean(s.person_url);
  if (!url || !s.signal_type) continue;
  const key = [s.platform || 'linkedin', s.signal_type, url, s.context_url || s.source_label || ''].join('|').toLowerCase();
  if (seen.has(key)) continue;
  seen.add(key);
  fresh.push({ ...s, person_url: url, dedup_key: key });
}
const stacks = {};
for (const r of history.concat(fresh)) {
  const url = clean(r.person_url);
  if (url) (stacks[url] = stacks[url] || new Set()).add(r.signal_type + ' / ' + (r.source_label || 'n/a'));
}
return fresh.map(s => {
  const headline = String(s.headline || '').slice(0, 300);
  const stack = [...(stacks[s.person_url] || [])];
  return { json: {
    dedup_key: s.dedup_key, person_url: s.person_url, person_name: s.person_name || '', headline,
    platform: s.platform || 'linkedin', signal_type: s.signal_type, source_label: s.source_label || '',
    context_text: String(s.context_text || '').slice(0, 1500), context_url: s.context_url || '',
    weight: Number(s.weight) || 1, stack_count: stack.length, stack_types: stack.join('; ').slice(0, 500),
    prefilter: !EXCLUDE.some(w => headline.toLowerCase().includes(w)) && !!s.person_name,
    score: 0, tier: 'unscored', opener: '', angle: '', why: '', routed: false,
    detected_at: new Date().toISOString()
  } };
});

// Four independent judgments per signal, asked in one Jev call.
// Jev returns probabilities, not prose. The next node turns them into a 0-100 score.
const cfg = $('SETUP').first().json;
const angles = {};
for (const [k, v] of Object.entries(cfg.angles)) angles[k] = v.means;
angles.none = 'None of these, or not enough context to tell';
const questions = {
  buyer_fit: { type: 'score',
    instructions: { question: 'How well does this `person` match the ideal buyer in `icp`? Judge the role and the kind of company their headline suggests. If `person` is a company rather than an individual, judge whether the company fits.', icp: cfg.icp },
    criteria: ['Clearly not a fit: matches something in icp.not_a_fit, or has no buying role', 'Unclear: not enough information about role or company', 'Partial fit: right kind of company but not a decision maker, or decision maker at a doubtful company', 'Strong fit: decision maker at a company that plausibly sells high-ticket through a sales team'] },
  pain_intent: { type: 'score',
    instructions: 'How strongly does `signal.text` show that this person (or company) is experiencing a sales-process problem right now? Reacting to someone else\'s post counts less than describing their own situation. Actively hiring sales roles counts as a moderate signal.',
    criteria: ['No evidence: a like or generic reaction, or text about something unrelated', 'Weak: agrees with or comments on the topic without describing their own situation', 'Moderate: describes the problem as relevant to their own team, or is hiring for it', 'Strong: describes their own current problem in concrete terms, or asks for help solving it'] },
  is_seller: { type: 'noul',
    instructions: { question: 'Is this person selling something related to `icp.what_we_sell` rather than buying it, for example a consultant, agency, coach, or software vendor promoting their own offer?', icp: cfg.icp } },
  angle: { type: 'choice', instructions: 'Which problem is closest to what `signal.text` is about?', criteria: angles }
};
return $input.all().map(it => ({ json: { ...it.json, jev_body: {
  model: 'jev-latest',
  state: {
    person: { name: it.json.person_name, headline: it.json.headline },
    signal: { type: it.json.signal_type, source: it.json.source_label, text: it.json.context_text },
    other_signals_last_30_days: it.json.stack_types
  },
  questions
} } }));

// Policy lives here, in code, so you can retune weights without re-asking Jev.
const cfg = $('SETUP').first().json;
const w = cfg.weights;
return $input.all().map((it, i) => {
  const base = $('Build Jev Questions').itemMatching(i).json;
  const a = it.json.answers;
  if (!a) return { json: { ...base, signal_row_id: base.id, score: 0, tier: 'error', opener: '', angle: '', why: 'Jev call failed: ' + JSON.stringify(it.json.error || it.json).slice(0, 200), is_hot: false } };
  const fit = (a.buyer_fit.score || 0) / 3;
  const pain = (a.pain_intent.score || 0) / 3;
  const seller = a.is_seller.noul || 0;
  const stacking = Math.min(Math.max((base.stack_count || 1) - 1, 0), 2) / 2;
  let raw = w.buyer_fit * fit + w.pain * pain + w.stacking * stacking;
  if (fit < 0.5) raw = Math.min(raw, 0.4);   // a non-buyer never goes hot, however loud the signal
  if (seller > 0.5) raw = raw * 0.2;          // sellers pitching the same thing are not leads
  const score = Math.round(raw * 100);
  const angle = a.angle.choice || 'none';
  const opener = cfg.angles[angle] ? cfg.angles[angle].opener : '';
  return { json: {
    ...base, signal_row_id: base.id, score, angle, opener,
    tier: score >= cfg.hot_score ? 'hot' : score >= 40 ? 'warm' : 'cold',
    why: 'fit ' + fit.toFixed(2) + ' | pain ' + pain.toFixed(2) + ' | seller ' + seller.toFixed(2) + ' | stack ' + base.stack_count + ' | angle ' + angle + ' (' + (a.angle.confidence || 0).toFixed(2) + ')',
    is_hot: score >= cfg.hot_score
  } };
});

// Adds name, company and email from the Apify lookup when it ran. Matches by LinkedIn slug.
const leads = $('Live LinkedIn Lead?').all().map(i => i.json);
const profiles = $('Enrich Hot Leads').isExecuted ? $('Enrich Hot Leads').all().map(i => i.json).filter(p => p && (p.linkedinUrl || p.publicIdentifier)) : [];
const slug = u => { const m = String(u || '').match(/linkedin\.com\/in\/([^\/?#]+)/i); return m ? decodeURIComponent(m[1]).toLowerCase() : ''; };
const findEmail = (o, d = 0) => {
  if (d > 6 || o === null || o === undefined) return '';
  if (typeof o === 'string') return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(o) ? o : '';
  if (typeof o === 'object') { for (const k in o) { const r = findEmail(o[k], d + 1); if (r) return r; } }
  return '';
};
const company = p => (p.currentPosition && p.currentPosition[0] && p.currentPosition[0].companyName) || (p.experience && p.experience[0] && p.experience[0].companyName) || '';
return leads.map(lead => {
  const s = slug(lead.person_url);
  const p = profiles.find(x => slug(x.linkedinUrl) === s || String(x.publicIdentifier || '').toLowerCase() === s) || {};
  const name = String(lead.person_name || '').split(' ');
  return { json: { ...lead,
    profile_url: p.linkedinUrl || lead.person_url,
    first_name: p.firstName || name[0] || '',
    last_name: p.lastName || name.slice(1).join(' '),
    company: company(p),
    email: findEmail(p.emails || p.email || '')
  } };
});

// Up to 100 leads per HeyReach call. The opener rides along as the custom variable {signal_opener}.
const cfg = $('SETUP').first().json;
const field = (name, value) => ({ name, value: String(value || '').slice(0, 500) });
const pairs = $input.all().map(i => i.json).map(l => ({
  linkedInAccountId: Number(cfg.heyreach_sender_account_id),
  lead: {
    firstName: l.first_name, lastName: l.last_name, profileUrl: l.profile_url, emailAddress: l.email || null,
    companyName: l.company, position: l.headline,
    customUserFields: [field('signal_opener', l.opener), field('signal_type', l.signal_type), field('signal_source', l.source_label), field('signal_score', l.score)]
  }
}));
const out = [];
for (let i = 0; i < pairs.length; i += 100) out.push({ json: { payload: { campaignId: Number(cfg.heyreach_campaign_id), accountLeadPairs: pairs.slice(i, i + 100) } } });
return out;

// Marks rows as routed only when HeyReach accepted the batch.
const ok = $input.all().some(i => !i.json.error);
return ok ? $('Attach Enrichment').all().map(i => ({ json: { signal_row_id: i.json.signal_row_id } })) : [];

